<script setup>
import { computed, reactive, ref, watch, nextTick } from 'vue';
import { ChevronLeft, ChevronRight, Download, Upload } from '@lucide/vue';
import AppDialog from './AppDialog.vue';
import FormField from './FormField.vue';
import { state, importProjectPackage, notify } from '../state';
import { storage } from '../storage';
import { t, number, errorText } from '../i18n';
import { projectExportManifest } from '../../core/project-package.mjs';
import { BACKUP_LIMIT } from '../../core/files.mjs';
const props=defineProps({projectId:String}),emit=defineEmits(['close','imported']);
const exporting=computed(()=>Boolean(props.projectId));
const options=reactive({includeRecipient:false,includePrivateNotes:false,includeSessions:false,includeSessionNotes:false,includeHistory:false,includeMarkers:false,attachmentIds:[]});
const busy=ref(false),error=ref(''),token=ref(''),sourceText=ref(''),fileName=ref(''),preview=ref(null),page=ref(1),attachmentPage=ref(1);
const decisions=reactive({name:'',materials:[],allowRepeat:false,resetProgress:false});
const materialReview=ref();
const unresolved=computed(()=>decisions.materials.filter(row=>!row.action).length);
async function reviewNext(){const index=decisions.materials.findIndex(row=>!row.action);if(index>=0)page.value=Math.floor(index/20)+1;await nextTick();materialReview.value?.scrollIntoView({behavior:'smooth',block:'start'});}
const privacyFields=['includeRecipient','includePrivateNotes','includeSessions','includeSessionNotes','includeHistory','includeMarkers'];
function message(caught){const key=`error.${caught?.code||''}`;return t(key)===key?errorText(caught):t(key);}
const availableManifest=computed(()=>{if(!exporting.value)return{value:null,error:''};try{return{value:projectExportManifest(state.value,props.projectId,{...options,attachmentIds:[]}),error:''};}catch(caught){return{value:null,error:message(caught)};}});
const choices=computed(()=>availableManifest.value.value?.attachmentChoices??[]);
watch(choices,list=>{const allowed=new Set(list.map(row=>row.id));const filtered=options.attachmentIds.filter(id=>allowed.has(id));if(filtered.length!==options.attachmentIds.length)options.attachmentIds=filtered;});
const selectedManifest=computed(()=>{if(!exporting.value)return{value:null,error:''};try{return{value:projectExportManifest(state.value,props.projectId,{...options,attachmentIds:options.attachmentIds.filter(id=>choices.value.some(row=>row.id===id))}),error:''};}catch(caught){return{value:null,error:message(caught)};}});
const manifest=computed(()=>selectedManifest.value.value);
const exportError=computed(()=>availableManifest.value.error||selectedManifest.value.error);
const attachmentPages=computed(()=>Math.max(1,Math.ceil(choices.value.length/10))),visibleAttachments=computed(()=>choices.value.slice((attachmentPage.value-1)*10,attachmentPage.value*10));
watch(attachmentPages,value=>{attachmentPage.value=Math.min(attachmentPage.value,value);});
const pages=computed(()=>Math.max(1,Math.ceil((preview.value?.materials.length||0)/20))),rows=computed(()=>preview.value?.materials.slice((page.value-1)*20,page.value*20)||[]);
const ready=computed(()=>preview.value&&decisions.name.trim()&&decisions.materials.every(row=>row.action)&&(!preview.value.repeat||decisions.allowRepeat));
function choiceFor(id){return decisions.materials.find(row=>row.sourceId===id);}
function selectMaterial(id,value){const row=choiceFor(id);row.action=value==='create'?'create':value.startsWith('reuse:')?'reuse':'';row.materialId=value.startsWith('reuse:')?value.slice(6):undefined;row.reviewed=true;}
function createAll(){for(const row of decisions.materials){row.action='create';delete row.materialId;row.reviewed=true;}}
async function exportPackage(){busy.value=true;error.value='';try{const text=await storage.exportProject(props.projectId,JSON.parse(JSON.stringify(options)));const title=state.value.projects.find(row=>row.id===props.projectId)?.name||'Ricamo';const name=title.replace(/[<>:"/\\|?*\u0000-\u001f]/g,'-').slice(0,100)+'.ricamoproject';if(await storage.saveFile({name,data:text}))notify();}catch(caught){error.value=message(caught);}finally{busy.value=false;}}
async function inspect(){busy.value=true;error.value='';try{const result=await storage.inspectProject(sourceText.value);token.value=result.token;preview.value=result.preview;decisions.name=result.preview.name;decisions.allowRepeat=false;decisions.resetProgress=false;decisions.materials=result.preview.materials.map(row=>({sourceId:row.sourceId,action:row.needsReview?'':row.recommendedId?'reuse':'create',...(row.recommendedId?{materialId:row.recommendedId}:{}),reviewed:!row.needsReview}));page.value=1;}catch(caught){token.value='';preview.value=null;error.value=message(caught);}finally{busy.value=false;}}
async function chooseFile(event){const file=event.target.files?.[0];if(!file)return;error.value='';try{if(file.size>BACKUP_LIMIT)throw Object.assign(new Error(),{code:'file_too_large'});sourceText.value=await file.text();fileName.value=file.name;await inspect();}catch(caught){error.value=message(caught);}event.target.value='';}
async function importPackage(){if(!ready.value||!token.value)return;busy.value=true;error.value='';const captured=token.value;token.value='';try{const result=await importProjectPackage(captured,JSON.parse(JSON.stringify(decisions)));notify();emit('imported',result.projectId);}catch(caught){error.value=message(caught);}finally{busy.value=false;}}
</script>
<template>
  <AppDialog :title="t(exporting?'exportProjectPackage':'importProjectPackage')" wide :busy="busy" @close="emit('close')">
    <p class="notice">{{ t('projectPackageHelp') }}</p><p v-if="error || exportError" class="notice error" role="alert">{{ error || exportError }}</p>
    <template v-if="exporting"><h3>{{ t('packagePrivacy') }}</h3><div class="stack"><label v-for="field in privacyFields" :key="field" class="checkbox-label"><input v-model="options[field]" type="checkbox" :disabled="field==='includeSessionNotes'&&!options.includeSessions" />{{ t(`package_${field}`) }}</label></div><p class="field-help">{{ t('packagePrivacyHelp') }}</p><p class="notice">{{t('packageCatalogueProjectionHelp')}}</p><p v-if="options.includeMarkers" class="field-help">{{ t('packageMarkersHelp') }}</p><p v-if="options.includeMarkers && manifest?.markerOmissions.length" class="notice warning">{{ t('packageMarkerOmissions',{count:manifest.markerOmissions.length}) }}</p><p v-if="options.includeSessions" class="field-help">{{ t('packageMeasuredSessionsHelp') }}</p>
      <section class="form-section"><h3>{{ t('packageFiles') }}</h3><p class="field-help">{{ t('packageFilesHelp') }}</p><p v-if="!choices.length" class="muted">{{ t('noPackageFiles') }}</p><div v-for="attachment in visibleAttachments" :key="attachment.id" class="stat-row"><label class="checkbox-label"><input v-if="attachment.required" type="checkbox" checked disabled /><input v-else v-model="options.attachmentIds" type="checkbox" :value="attachment.id" />{{ attachment.name }}</label><span>{{ number(attachment.size/1024,0) }}KB <span v-if="attachment.required" class="badge">{{ t('requiredReferenceFile') }}</span></span></div><div v-if="attachmentPages>1" class="actions"><button class="icon-button" :aria-label="t('previousPage')" :disabled="attachmentPage===1" @click="attachmentPage--"><ChevronLeft :size="18" /></button><span>{{ attachmentPage }}/{{ attachmentPages }}</span><button class="icon-button" :aria-label="t('nextPage')" :disabled="attachmentPage===attachmentPages" @click="attachmentPage++"><ChevronRight :size="18" /></button></div></section>
      <section v-if="manifest" class="form-section"><h3>{{ t('packageManifest') }}</h3><div v-for="key in ['materials','patterns','revisions','needs','tasks','sessions','attachments','history','markers']" :key="key" class="stat-row"><span>{{ t(`package_count_${key}`) }}</span><strong>{{ manifest.counts[key] }}</strong></div><p class="notice">{{ t('packageNoStock') }}</p></section>
    </template>
    <template v-else><FormField :label="t('projectPackageFile')" v-slot="{id}"><input :id="id" type="file" accept=".ricamoproject,application/json" :disabled="busy" @change="chooseFile" /></FormField><p v-if="fileName" class="field-help">{{ fileName }}</p>
      <template v-if="preview"><section class="form-section"><h3>{{ t('packageManifest') }}</h3><FormField :label="t('importedProjectName')" required v-slot="{id}"><input :id="id" v-model="decisions.name" maxlength="300" /></FormField><div v-for="key in ['materials','patterns','needs','tasks','sessions','attachments','history','markers']" :key="key" class="stat-row"><span>{{ t(`package_count_${key}`) }}</span><strong>{{ preview.counts[key] }}</strong></div><p>{{ t('packageProgress',{count:preview.counts.completed,percent:number(preview.counts.manualPercent)}) }}</p><p class="notice">{{ t('packageNoStock') }}</p><p v-if="preview.fabric" class="notice">{{ t('packageFabricPlan') }}</p><p v-if="preview.repeat" class="notice warning">{{ t('packageRepeated') }}</p><label v-if="preview.repeat" class="checkbox-label"><input v-model="decisions.allowRepeat" type="checkbox" />{{ t('packageAllowRepeat') }}</label><label class="checkbox-label form-section"><input v-model="decisions.resetProgress" type="checkbox" />{{ t('packageResetProgress') }}</label><p class="field-help">{{ t('packageImportStatus') }}</p></section>
      <section ref="materialReview" class="form-section"><div class="split-heading"><h3>{{ t('packageMaterialReview') }}</h3><button class="button small" @click="createAll">{{ t('packageCreateAll') }}</button></div><p class="field-help">{{ t('packageMaterialHelp') }}</p><div class="table-wrap"><table><thead><tr><th>{{ t('name') }}</th><th>{{ t('code') }}</th><th>{{ t('unit') }}</th><th>{{ t('packageMatchAction') }}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.sourceId"><td>{{ row.name }}<small class="cell-subtitle">{{ row.brand }} {{ row.range }}</small><small v-if="!row.conversionKnown" class="cell-subtitle">{{ t('packageUnknownConversion') }}</small></td><td class="mono">{{ row.code || '—' }}</td><td>{{ t(`unit_${row.unit}`) }}</td><td><select :aria-label="`${t('packageMatchAction')}: ${row.name}`" :value="choiceFor(row.sourceId).action==='reuse'?`reuse:${choiceFor(row.sourceId).materialId}`:choiceFor(row.sourceId).action==='create'?'create':''" @change="selectMaterial(row.sourceId,$event.target.value)"><option value="" disabled>{{ t('packageChooseMatch') }}</option><option value="create">{{ t('packageCreateMaterial') }}</option><option v-for="match in row.matches.filter(item=>item.compatible)" :key="match.id" :value="`reuse:${match.id}`">{{ t('packageUseExisting') }}: {{ match.name }} · {{ match.id.slice(0,8) }}</option></select></td></tr></tbody></table></div><div v-if="pages>1" class="panel-heading"><span>{{ t('page') }} {{ page }}/{{ pages }}</span><div class="actions"><button class="icon-button" :aria-label="t('previousPage')" :disabled="page===1" @click="page--"><ChevronLeft :size="18" /></button><button class="icon-button" :aria-label="t('nextPage')" :disabled="page===pages" @click="page++"><ChevronRight :size="18" /></button></div></div></section>
      </template>
    </template>
    <template #footer><button v-if="!exporting && unresolved" class="button text" @click="reviewNext">{{ t('packageUnresolved',{count:unresolved}) }}</button><button class="button" :disabled="busy" @click="emit('close')">{{ t('cancel') }}</button><button v-if="exporting" class="button primary" :disabled="busy||!manifest" @click="exportPackage"><Download :size="16" />{{ t('downloadProjectPackage') }}</button><button v-else-if="preview&&!token" class="button primary" :disabled="busy" @click="inspect">{{ t('refreshPackagePreview') }}</button><button v-else class="button primary" :disabled="busy||!ready||!token" @click="importPackage"><Upload :size="16" />{{ t('confirmProjectImport') }}</button></template>
  </AppDialog>
</template>
